function [k] = fsw_bdot_gain(scale, n, inc_deg, ii)
%FSW_BDOT_GAIN  The B-dot gain [A m^2 s]: scale 2 n (1 + sin i) J_min (Avanzini and Giulietti 2012), i the inclination [deg], J_min the
%   smallest principal inertia, scale the scenario's (fsw_tune_bdot_gain_scale when it states none).
%   scale: real[1] (passed a plain number)
%   n: real[1] (passed a plain number)
%   inc_deg: real[1] (passed a plain number)
%   ii: real[1][3] (passed a plain number)
%   returns k: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    k = 0;
    jmin = asils.pc.fmin(asils.pc.fmin(ii(1), ii(2)), ii(3));
    k = ((((scale * 2) * n) * (1 + sin(((inc_deg * pi) / 180)))) * jmin);
end
